public final class Money {                    // final: no subclass can add mutability
    private final long amount;                // minor units (paisa / cents), never double
    private final String currency;

    public Money(long amount, String currency) {
        if (amount < 0) throw new IllegalArgumentException("amount must be >= 0");
        this.amount = amount;
        this.currency = currency;
    }

    public Money plus(Money other) {          // "modifiers" return a NEW object
        if (!currency.equals(other.currency)) throw new IllegalArgumentException("currency mismatch");
        return new Money(amount + other.amount, currency);
    }

    public long amount() { return amount; }
    public String currency() { return currency; }
}
// Java 16+: record Money(long amount, String currency) { } gives the same shape + equals/hashCode

