import java.util.List;

// ABSTRACTION: callers only need "every Shape has a name and an area"
abstract class Shape {
    private final String name;                 // ENCAPSULATION: state is private

    protected Shape(String name) { this.name = name; }

    public String getName() { return name; }   // controlled, read-only access
    public abstract double area();             // WHAT, not HOW

    public String describe() {                 // shared behaviour, written once
        return "%s with area %.2f".formatted(name, area());
    }
}

// INHERITANCE: Circle IS-A Shape and reuses describe()
class Circle extends Shape {
    private final double radius;

    Circle(double radius) {
        super("Circle");
        this.radius = radius;
    }

    @Override
    public double area() { return Math.PI * radius * radius; }
}

class Rectangle extends Shape {
    private final double width, height;

    Rectangle(double width, double height) {
        super("Rectangle");
        this.width = width;
        this.height = height;
    }

    @Override
    public double area() { return width * height; }
}

public class Main {
    public static void main(String[] args) {
        // POLYMORPHISM: one call site, the runtime type picks the area() to run
        List<Shape> shapes = List.of(new Circle(1), new Rectangle(3, 4));
        for (Shape s : shapes) {
            System.out.println(s.describe());
        }
        // Output:
        // Circle with area 3.14
        // Rectangle with area 12.00
    }
}

