class Car {
    String color;                  // instance field: every object gets its own copy

    Car(String color) {
        this.color = color;
    }
}

public class Main {
    public static void main(String[] args) {
        Car a = new Car("Red");    // object #1 created on the heap
        Car b = new Car("Blue");   // object #2 created on the heap
        Car c = a;                 // NO new object: c copies the reference to #1

        c.color = "Green";         // change object #1 through c ...
        System.out.println(a.color);   // Green  (... and a sees it)
        System.out.println(b.color);   // Blue
        System.out.println(a == c);    // true   (same object)
        System.out.println(a == b);    // false  (different objects)

        a = null;                  // #1 is still reachable through c
        c = null;                  // nothing points to #1 -> eligible for garbage collection
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class BankAccount {
    private final String accountNo;
    private long balance;                        // whole taka; invariant: never negative
    private final List<String> history = new ArrayList<>();

    public BankAccount(String accountNo) {
        this.accountNo = accountNo;
    }

    public void deposit(long amount) {
        if (amount <= 0) throw new IllegalArgumentException("Deposit must be positive");
        balance += amount;
        history.add("DEPOSIT " + amount);
    }

    public void withdraw(long amount) {
        if (amount <= 0) throw new IllegalArgumentException("Withdrawal must be positive");
        if (amount > balance) throw new IllegalStateException("Insufficient funds");
        balance -= amount;
        history.add("WITHDRAW " + amount);
    }

    public long getBalance() { return balance; }  // read access only: there is no setBalance()

    public List<String> getHistory() {
        return Collections.unmodifiableList(history);   // callers cannot edit our list
    }
}

class Main {
    public static void main(String[] args) {
        BankAccount acc = new BankAccount("ACC-1001");
        acc.deposit(5_000);
        try {
            acc.withdraw(8_000);
        } catch (IllegalStateException e) {
            System.out.println("Rejected: " + e.getMessage());   // Rejected: Insufficient funds
        }
        acc.withdraw(1_500);
        System.out.println(acc.getBalance());                    // 3500
        // acc.balance = -100;   // compile error: balance has private access in BankAccount
        try {
            acc.getHistory().add("WITHDRAW 999999");
        } catch (UnsupportedOperationException e) {
            System.out.println("History is read-only");
        }
        System.out.println(acc.getHistory());                    // [DEPOSIT 5000, WITHDRAW 1500]
    }
}

class BankAccount:
