// ABSTRACTION: callers see WHAT a gateway can do, nothing about HOW
interface PaymentGateway {
    String pay(String phone, long amount);
}

// ENCAPSULATION: the HOW and its data are hidden and protected inside the class
class MobileWalletGateway implements PaymentGateway {
    private final String apiKey;              // secret: never leaves this class
    private String sessionToken;              // internal state
    private int requestCount = 0;

    MobileWalletGateway(String apiKey) { this.apiKey = apiKey; }

    @Override
    public String pay(String phone, long amount) {
        ensureSession();                      // hidden step the caller never sees
        requestCount++;
        return "TXN-" + requestCount + ": " + amount + " BDT to " + phone;
    }

    private void ensureSession() {            // private helper
        if (sessionToken == null) sessionToken = "session-" + apiKey.length();
    }
}

class CheckoutService {
    private final PaymentGateway gateway;     // depends on the abstraction only

    CheckoutService(PaymentGateway gateway) { this.gateway = gateway; }

    String checkout(String phone, long amount) { return gateway.pay(phone, amount); }
}

