class Printer {
    // OVERLOADING: same name, different parameter lists, chosen by the compiler
    String print(Object o) { return "Object: " + o; }
    String print(String s) { return "String: " + s; }
    String print(int n)    { return "int: " + n; }
}

public class Main {
    public static void main(String[] args) {
        Animal a = new Dog();                    // declared (static) type Animal, runtime type Dog
        System.out.println(a.sound());           // Woof   -> picked at RUNTIME from the object
        System.out.println(a.kind());            // Animal -> static methods bind to the declared type

        Printer p = new Printer();
        Object o = "hello";                      // static type Object, runtime type String
        System.out.println(p.print("hello"));    // String: hello
        System.out.println(p.print(o));          // Object: hello -> picked at COMPILE time
        System.out.println(p.print(42));         // int: 42
    }
}

