// INTERFACE = a capability / contract. Many can be implemented by one class.
interface Refundable {
    int MAX_REFUND_DAYS = 7;                          // implicitly public static final

    boolean refund(String txnId);                     // implicitly public abstract

    default String refundPolicy() {                   // Java 8+: default method with a body
        return "Refunds within " + MAX_REFUND_DAYS + " days" + suffix();
    }

    private String suffix() { return "."; }           // Java 9+: private helper method

    static Refundable none() { return txnId -> false; }   // Java 8+: static factory method
}

// ABSTRACT CLASS = a partially built base: shared state + constructor + template method
abstract class Payment {
    protected final long amount;
    private int attempts = 0;                         // instance state: interfaces cannot have this

    protected Payment(long amount) { this.amount = amount; }

    public final String process() {                   // template method: fixed algorithm
        attempts++;
        return validate() ? charge() + " (attempt " + attempts + ")" : "invalid amount";
    }

    protected boolean validate() { return amount > 0; }   // hook with a default
    protected abstract String charge();                   // the step subclasses must fill in
}

// A class extends ONE abstract class but can implement MANY interfaces
class CardPayment extends Payment implements Refundable {
    CardPayment(long amount) { super(amount); }

    @Override protected String charge() { return "Charged card " + amount; }
    @Override public boolean refund(String txnId) { return txnId.startsWith("TXN"); }
}

public class Main {
    public static void main(String[] args) {
        CardPayment p = new CardPayment(500);
        System.out.println(p.process());                        // Charged card 500 (attempt 1)
        System.out.println(p.refund("TXN-9"));                  // true
        System.out.println(p.refundPolicy());                   // Refunds within 7 days.
        System.out.println(Refundable.none().refund("TXN-9"));  // false
        // new Payment(10);  -> compile error: Payment is abstract; cannot be instantiated
    }
}

