import java.util.Collection;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

// INHERITANCE: our class silently depends on HOW HashSet implements addAll()
class CountingHashSet<E> extends HashSet<E> {
    int addCount = 0;

    @Override public boolean add(E e) {
        addCount++;
        return super.add(e);
    }

    @Override public boolean addAll(Collection<? extends E> c) {
        addCount += c.size();
        return super.addAll(c);          // HashSet's addAll calls add() for each element ...
    }                                    // ... which is OUR add() -> every element counted twice
}

// COMPOSITION: wrap a Set and forward calls. Only Set's public contract matters.
class CountingSet<E> {
    private final Set<E> inner;          // HAS-A set
    int addCount = 0;

    CountingSet(Set<E> inner) { this.inner = inner; }

    public boolean add(E e) {
        addCount++;
        return inner.add(e);
    }

    public boolean addAll(Collection<? extends E> c) {
        addCount += c.size();
        return inner.addAll(c);          // inner.add() is HashSet's own add, not ours
    }

    public int size() { return inner.size(); }
}

public class Main {
    public static void main(String[] args) {
        CountingHashSet<String> s1 = new CountingHashSet<>();
        s1.addAll(List.of("a", "b", "c"));
        System.out.println(s1.addCount);     // 6  <- bug caused by inheritance

        CountingSet<String> s2 = new CountingSet<>(new HashSet<>());
        s2.addAll(List.of("a", "b", "c"));
        System.out.println(s2.addCount);     // 3  <- correct
    }
}

