class Base {
    static { System.out.println("1. Base static block"); }       // once, when the class loads
    { System.out.println("3. Base instance block"); }            // every object, after super()

    Base() {
        this("default");                     // constructor chaining: must be the FIRST statement
        System.out.println("5. Base() body");
    }

    Base(String name) {
        // implicit super() -> Object()
        System.out.println("4. Base(String) body, name = " + name);
        hook();                              // DANGER: calls an overridable method
    }

    void hook() { }
}

class Child extends Base {
    static { System.out.println("2. Child static block"); }
    private String city = "Dhaka";           // field initializer runs AFTER super() returns

    Child() {
        super();                             // inserted by the compiler if you omit it
        System.out.println("7. Child() body, city = " + city);
    }

    { System.out.println("6. Child instance block, city = " + city); }

    @Override
    void hook() { System.out.println("   Child.hook() sees city = " + city); }   // null!
}

public class Main {
    public static void main(String[] args) {
        new Child();
        System.out.println("--- second object ---");
        new Child();
    }
}

