class User {
    private static int totalUsers = 0;              // ONE copy, owned by the class
    private static final String APP = "HireReady";  // constant shared by everyone

    private final int id;                           // one copy PER object
    private final String name;

    User(String name) {
        totalUsers++;                               // instance code may touch static state
        this.id = totalUsers;
        this.name = name;
    }

    static int getTotalUsers() {                    // no 'this' inside a static method
        // return name;  -> compile error: non-static variable name cannot be referenced from a static context
        return totalUsers;
    }

    String describe() {                             // instance method sees both kinds
        return APP + " user #" + id + " " + name + " (of " + totalUsers + ")";
    }
}

