// AFTER: each class has ONE job (high cohesion) and depends on small interfaces (loose coupling)
interface OrderRepository { void save(String orderId); }
interface Notifier { void send(String customer, String message); }

class OrderService {
    private final OrderRepository repo;
    private final Notifier notifier;

    OrderService(OrderRepository repo, Notifier notifier) {   // dependencies are handed in
        this.repo = repo;
        this.notifier = notifier;
    }

    void placeOrder(String orderId, String customer) {
        repo.save(orderId);
        notifier.send(customer, "Order " + orderId + " confirmed");
    }
}

// Swappable details: production uses a DB + SMS gateway, tests use these fakes
class InMemoryOrderRepository implements OrderRepository {
    final List<String> saved = new ArrayList<>();
    public void save(String orderId) { saved.add(orderId); }
}

class ConsoleNotifier implements Notifier {
    public void send(String customer, String message) {
        System.out.println("To " + customer + ": " + message);
    }
}

public class Main {
    public static void main(String[] args) {
